import torch, math

def attn_weight_row(Q, K, d_k, mask=None):
    S = (Q @ K.transpose(-2, -1)) / math.sqrt(d_k)
    if mask is not None:
        S = S.masked_fill(mask, float('-inf'))
    return torch.softmax(S, dim=-1)   # A[q, i] = weight on key i

